1	<!doctype html>
2	<html lang="zh-CN">
3	<meta charset="utf-8">
4	<meta name="viewport" content="width=device-width,initial-scale=1">
5	<title>ScoreArena · 桌面规则游戏与赛事管理</title>
6	<style>
7	  :root { color-scheme: light; }
8	  body { font-family: system-ui, sans-serif; max-width: 52rem; margin: 3rem auto; padding: 0 1rem; line-height: 1.7; color: #1f2933; }
9	  h1 { margin-bottom: .25rem; }
10	  .sub { color: #52606d; margin-top: 0; }
11	  h2 { margin-top: 2.5rem; border-bottom: 1px solid #e4e7eb; padding-bottom: .35rem; }
12	  a { color: #175b9c; }
13	  form { background: #f8f9fb; border: 1px solid #e4e7eb; border-radius: .5rem; padding: 1.25rem 1.5rem; }
14	  .field { display: grid; grid-template-columns: 9rem 1fr; gap: .75rem; align-items: center; margin-bottom: 1rem; }
15	  label { font-weight: 600; }
16	  input, select { font: inherit; padding: .4rem .55rem; border: 1px solid #cbd2d9; border-radius: .35rem; background: #fff; }
17	  input:focus, select:focus { outline: 2px solid #9ec5fe; outline-offset: 1px; border-color: #175b9c; }
18	  .hint { grid-column: 2; color: #616e7c; font-size: .9rem; margin: -.35rem 0 0; }
19	  .actions { grid-column: 2; margin-top: .25rem; }
20	  button { font: inherit; font-weight: 600; padding: .5rem 1.4rem; border: none; border-radius: .35rem; background: #175b9c; color: #fff; cursor: pointer; }
21	  button:disabled { background: #9aa5b1; cursor: wait; }
22	  .msg { margin: 1rem 0 0; padding: .6rem .9rem; border-radius: .35rem; display: none; }
23	  .msg.show { display: block; }
24	  .msg.error { background: #fde8e8; border: 1px solid #f5b5b5; color: #9b1c1c; }
25	  .msg.ok { background: #e6f6ec; border: 1px solid #a7e0bd; color: #146134; }
26	  .msg.warn { background: #fff8e6; border: 1px solid #f0d48a; color: #7c4a03; }
27	  table { width: 100%; border-collapse: collapse; font-size: .95rem; }
28	  th, td { text-align: left; padding: .55rem .6rem; border-bottom: 1px solid #e4e7eb; vertical-align: top; }
29	  th { color: #52606d; font-size: .85rem; white-space: nowrap; }
30	  td.id, code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: .85rem; word-break: break-all; }
31	  .empty { color: #616e7c; }
32	  .skip-notice { background: #fff8e6; border: 1px solid #f0d48a; color: #7c4a03; padding: .6rem .9rem; border-radius: .35rem; margin: 0 0 1rem; }
33	  .list-error { color: #9b1c1c; }
34	  .badge { display: inline-block; padding: .05rem .55rem; border-radius: 999px; background: #fff3c4; color: #7c4a03; font-size: .85rem; }
35	  .meta { color: #7b8794; font-size: .85rem; }
36	</style>
37	<main>
38	  <h1>ScoreArena</h1>
39	  <p class="sub">桌面规则游戏与赛事管理</p>
40	
41	  <h2>创建公开房间</h2>
42	  <form id="room-form" novalidate>
43	    <div class="field">
44	      <label for="name">房间名称</label>
45	      <input id="name" name="name" type="text" autocomplete="off"
46	             placeholder="1–40 个字符，首尾空白会被去掉" required>
47	      <p class="hint">名称会去掉首尾空白后保存，内部空格保留；长度按 Unicode 字符计。原始输入不限长，整理后不超过 40 个字符即可。</p>
48	    </div>
49	    <div class="field">
50	      <label for="game">游戏规则</label>
51	      <select id="game" name="game" required>
52	        <option value="" selected>请选择游戏规则…</option>
53	        <option value="gomoku">五子棋（gomoku）</option>
54	        <option value="ludo">飞行棋（ludo）</option>
55	      </select>
56	    </div>
57	    <div class="field">
58	      <label for="capacity">人数上限</label>
59	      <select id="capacity" name="capacity" required disabled>
60	        <option value="" selected>请先选择游戏规则</option>
61	      </select>
62	      <p class="hint" id="capacity-hint">五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。</p>
63	    </div>
64	    <div class="field">
65	      <label for="turnSeconds">每步时间限制</label>
66	      <input id="turnSeconds" name="turnSeconds" type="number" step="1" inputmode="numeric"
67	             placeholder="秒，0 表示不限时" required>
68	      <p class="hint">以秒为单位：填 <strong>0</strong> 表示不限时；其他值必须是 10 至 600 之间的整数。</p>
69	    </div>
70	    <div class="field">
71	      <div></div>
72	      <div class="actions">
73	        <button type="submit" id="submit">创建房间</button>
74	      </div>
75	    </div>
76	    <p class="msg" id="form-msg" role="alert"></p>
77	  </form>
78	
79	  <h2>房间列表</h2>
80	  <div id="list-area">
81	    <p class="empty" id="empty-tip">还没有房间记录。</p>
82	  </div>
83	
84	  <p class="meta"><a href="/api/rooms">查看房间列表接口</a> · <a href="/health">服务状态</a></p>
85	</main>
86	
87	<script>
88	(function () {
89	  var form = document.getElementById('room-form');
90	  var gameSel = document.getElementById('game');
91	  var capSel = document.getElementById('capacity');
92	  var capHint = document.getElementById('capacity-hint');
93	  var submitBtn = document.getElementById('submit');
94	  var formMsg = document.getElementById('form-msg');
95	  var listArea = document.getElementById('list-area');
96	  var emptyTip = document.getElementById('empty-tip');
97	
98	  // 映射表必须是无原型对象：历史值里可能恰好存着 "constructor"、"toString"、
99	  // "__proto__" 这类字符串，普通对象字面量会沿原型链查到内置函数或
100	  // Object.prototype，反而把函数源码或 [object Object] 当成中文映射显示。
101	  // 无原型对象查这些键一律得到 undefined，于是按未知值逐字回显原文。
102	  var GAME_LABELS = Object.create(null);
103	  GAME_LABELS.gomoku = '五子棋';
104	  GAME_LABELS.ludo = '飞行棋';
105	  var STATUS_LABELS = Object.create(null);
106	  STATUS_LABELS.waiting = '未开始';
107	
108	  // 按所选规则重建人数上限选项。
109	  function syncCapacity() {
110	    var game = gameSel.value;
111	    var prev = capSel.value;
112	    capSel.innerHTML = '';
113	    if (game === 'gomoku') {
114	      capSel.disabled = false;
115	      addOption('', '固定 2 人');
116	      addOption('2', '2 人');
117	      capSel.value = '2';
118	      capHint.textContent = '五子棋人数上限固定为 2 人。';
119	    } else if (game === 'ludo') {
120	      capSel.disabled = false;
121	      addOption('', '请选择人数上限…');
122	      [2, 3, 4].forEach(function (n) { addOption(String(n), n + ' 人'); });
123	      capSel.value = (prev === '2' || prev === '3' || prev === '4') ? prev : '';
124	      capHint.textContent = '飞行棋人数上限允许 2 至 4 人。';
125	    } else {
126	      capSel.disabled = true;
127	      addOption('', '请先选择游戏规则');
128	      capHint.textContent = '五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。';
129	    }
130	  }
131	
132	  function addOption(value, text) {
133	    var opt = document.createElement('option');
134	    opt.value = value;
135	    opt.textContent = text;
136	    capSel.appendChild(opt);
137	  }
138	
139	  gameSel.addEventListener('change', syncCapacity);
140	
141	  function showMessage(kind, text) {
142	    formMsg.className = 'msg show ' + kind;
143	    formMsg.textContent = text;
144	  }
145	  function clearMessage() {
146	    formMsg.className = 'msg';
147	    formMsg.textContent = '';
148	  }
149	
150	  // 与服务端 strings.TrimSpace（Go unicode.IsSpace）完全一致的首尾空白范围：
151	  // 包含 U+0085、U+00A0 等，但不包含 U+FEFF（保留并计入长度）。
152	  // 不能用 JS 自带的 trim()：它会多去掉 U+FEFF，又漏掉 U+0085。
153	  var EDGE_SPACE = '[\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]';
154	  var LEADING_SPACE = new RegExp('^' + EDGE_SPACE + '+');
155	  var TRAILING_SPACE = new RegExp(EDGE_SPACE + '+$');
156	  function trimName(value) {
157	    return value.replace(LEADING_SPACE, '').replace(TRAILING_SPACE, '');
158	  }
159	
160	  // 与服务端一致的提交前校验；服务端仍会再次校验。
161	  // 输入表单原始值，返回 { error } 或 { payload }：漏填要明确报错，绝不补默认值；
162	  // 名称只含会被去掉的首尾空白时同样视为空。通过校验的 payload 中名称仍是
163	  // 用户原始输入（不由页面整理），时间与人数各只转换一次。
164	  function checkForm(raw) {
165	    var nameLen = Array.from(trimName(raw.name)).length;
166	    if (nameLen === 0) return { error: '房间名称不能为空。' };
167	    if (!raw.game) return { error: '请选择游戏规则。' };
168	    if (raw.capacity === '') return { error: '请选择人数上限。' };
169	    if (raw.turnSeconds === '') return { error: '请填写每步时间限制（0 表示不限时）。' };
170	    if (!/^-?\d+$/.test(raw.turnSeconds)) return { error: '时间限制必须是整数秒，不能含小数。' };
171	
172	    // 通过必填与整数格式检查后再转换：空值不会变成 0，不合法文字不会变成秒数。
173	    var capacity = parseInt(raw.capacity, 10);
174	    var turnSeconds = Number(raw.turnSeconds);
175	
176	    if (nameLen > 40) return { error: '房间名称去掉首尾空白后不能超过 40 个字符。' };
177	    if (raw.game !== 'gomoku' && raw.game !== 'ludo') return { error: '请选择游戏规则。' };
178	    if (raw.game === 'gomoku' && capacity !== 2) return { error: '五子棋的人数上限固定为 2 人。' };
179	    if (raw.game === 'ludo' && !(capacity >= 2 && capacity <= 4)) {
180	      return { error: '飞行棋的人数上限必须为 2 至 4 人。' };
181	    }
182	    if (turnSeconds !== 0 && !(turnSeconds >= 10 && turnSeconds <= 600)) {
183	      return { error: '每步时间限制只能填 0（不限时）或 10 至 600 之间的整数秒。' };
184	    }
185	
186	    return {
187	      payload: {
188	        name: raw.name,
189	        game: raw.game,
190	        capacity: capacity,
191	        turnSeconds: turnSeconds
192	      }
193	    };
194	  }
195	
196	  // 是否已有一次创建请求在途。等待期间表单四项仍可继续编辑（规则与人数
197	  // 的联动照常生效），但不能再次提交：按钮在本次提交及随后的列表刷新
198	  // 完成前保持禁用，这里再加一道防线，阻止通过回车键等方式触发第二次
199	  // 提交。等待期间的编辑只影响表单本身：既不改变已提交的配置，也不会
200	  // 自动再发出一次创建请求。
201	  var submitting = false;
202	
203	  // 读取表单四项在页面上的实际填写值（名称保留首尾空白的原貌，不做整理）。
204	  // 提交时与响应到达时各读一次并逐项比较，据此决定成功后是否复位表单。
205	  function nameInput() { return document.getElementById('name'); }
206	  function turnSecondsInput() { return document.getElementById('turnSeconds'); }
207	  function readFormValues() {
208	    return {
209	      name: nameInput().value,
210	      game: gameSel.value,
211	      capacity: capSel.value,
212	      turnSeconds: turnSecondsInput().value
213	    };
214	  }
215	
216	  form.addEventListener('submit', function (event) {
217	    event.preventDefault();
218	    if (submitting) return;
219	    clearMessage();
220	
221	    var result = checkForm({
222	      name: nameInput().value,
223	      game: gameSel.value,
224	      capacity: capSel.value,
225	      turnSeconds: turnSecondsInput().value.trim()
226	    });
227	    if (result.error) { showMessage('error', result.error); return; }
228	
229	    submit(result.payload);
230	  });
231	
232	  // 表单复位到初始状态：名称与时间清空、规则未选、人数不可填写。
233	  // 仅在创建成功且等待期间四项填写值与提交时完全一致时调用。
234	  function resetForm() {
235	    form.reset();
236	    syncCapacity();
237	  }
238	
239	  function submit(payload) {
240	    submitting = true;
241	    submitBtn.disabled = true;
242	
243	    // 点击提交瞬间四项的实际填写值快照。本次房间固定按 payload（即点击时
244	    // 的配置）创建；响应到达时再读一次当前值与之逐项比较。
245	    var submittedValues = readFormValues();
246	
247	    fetch('/api/rooms', {
248	      method: 'POST',
249	      headers: { 'Content-Type': 'application/json' },
250	      body: JSON.stringify(payload)
251	    }).then(function (resp) {
252	      // 记录正文是否完整读出并解析为 JSON。状态码已收到（如 201）但正文
253	      // 为空、被截断或读取中断时，bodyOk 为 false：此时不能拿解析失败的
254	      // 空数据冒充创建结果（否则会显示“编号：undefined”）。
255	      return resp.json().then(function (data) {
256	        return { ok: resp.ok, status: resp.status, data: data, bodyOk: true };
257	      }, function () {
258	        return { ok: resp.ok, status: resp.status, data: null, bodyOk: false };
259	      });
260	    }).then(function (result) {
261	      if (result.ok && result.status === 201) {
262	        // 只有正文完整读出、能解析且带有非空编号，才算拿到本次创建结果。
263	        var createdId = result.bodyOk && result.data &&
264	          typeof result.data.id === 'string' && result.data.id !== ''
265	          ? result.data.id : null;
266	
267	        if (createdId === null) {
268	          // 已收到 201 但创建结果未能确认：房间可能已经在服务端保存。
269	          // 不承诺创建失败、不显示成功编号、不凭空拼房间或猜编号，
270	          // 不自动重发本次提交，也不清空或改动房间列表；表单四项以页面
271	          // 当前实际填写为准整体保留（含等待期间的修改，不整理名称首尾
272	          // 空白、不补齐未填项），提醒用户先刷新页面核对列表再决定。
273	          showMessage('warn', '创建结果未能确认：服务已返回成功状态，但回应内容未能完整读取，' +
274	            '房间可能已经保存。请先刷新页面查看房间列表，确认是否已创建后，再决定是否重新提交。');
275	          return;
276	        }
277	
278	        var okText = '房间已创建，编号：' + createdId;
279	
280	        // 是否复位以页面当前实际填写值为准，与提交时快照逐项比较：
281	        // 四项全部一致（含等待期间改过又完整恢复）才恢复初始表单；
282	        // 任一项不同——哪怕只动了名称的首尾空白——都整体保留当前四项
283	        // 及其对应的人数选择状态，不能只留改过的项，也不能把其他项
284	        // 恢复成旧配置；内容没填完整同样原样保留、不自动补齐。
285	        var currentValues = readFormValues();
286	        var unchanged = currentValues.name === submittedValues.name &&
287	          currentValues.game === submittedValues.game &&
288	          currentValues.capacity === submittedValues.capacity &&
289	          currentValues.turnSeconds === submittedValues.turnSeconds;
290	
291	        if (unchanged) {
292	          showMessage('ok', okText);
293	          resetForm();
294	        } else {
295	          // 本次房间已按提交时的配置创建并生成编号；表单中是等待期间
296	          // 继续填写、尚未提交的新配置，不会自动创建下一间房，完整保留
297	          // 供用户处理完成后直接再次提交。
298	          showMessage('ok', okText + '。表单中当前填写的内容尚未提交，不会自动创建房间；' +
299	            '如需创建下一间，可直接点击“创建房间”。');
300	        }
301	        return loadRooms();
302	      }
303	      // 创建失败（被服务拒绝）：不触碰表单，等待期间的最新填写原样保留，
304	      // 不回退到提交时的值，仅显示服务给出的原因。
305	      var reason = result.data && result.data.error ? result.data.error
306	                 : ('创建失败（HTTP ' + result.status + '）');
307	      showMessage('error', reason);
308	    }).catch(function () {
309	      // 连接失败同样保留当时最新的填写内容。
310	      showMessage('error', '无法连接服务，请确认服务仍在运行后重试。');
311	    }).finally(function () {
312	      submitting = false;
313	      submitBtn.disabled = false;
314	    });
315	  }
316	
317	  // 创建时间列的三种正常展示（对象/数组已由 buildRoomRow 统一判为异常，
318	  // 不会进入这里）：
319	  //   1. 能解析成有效日期的字符串：按浏览器本地时区显示
320	  //      YYYY-MM-DD HH:mm:ss（带时区偏移的时间换算成实际对应的本地时刻，
321	  //      不把原串里的时分当本地时间），悬浮提示保留接口返回的原始字符串；
322	  //   2. 无法解析的非空字符串：原文直接显示在单元格中（textContent 保证
323	  //      尖括号等字符只作为文字呈现），不替换为当前时间，不附悬浮说明；
324	  //   3. 字段缺失、null 或空字符串：单元格留空且没有悬浮说明，
325	  //      绝不由页面生成 undefined 或 Invalid Date。
326	  function renderTimeCell(td, value) {
327	    if (value == null || value === '') return;
328	
329	    var d = new Date(value);
330	    if (isNaN(d.getTime())) {
331	      td.textContent = typeof value === 'string' ? value : String(value);
332	      return;
333	    }
334	
335	    var pad = function (n) { return String(n).padStart(2, '0'); };
336	    td.textContent = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
337	      ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
338	    td.title = typeof value === 'string' ? value : String(value);
339	  }
340	
341	  // 只有 JSON 对象能作为房间行；null、字符串、数字、布尔值和数组都跳过。
342	  // 不按创建表单的规则重新判定历史记录：对象带多少附加字段都照常展示，
343	  // 也不检查其字段是否完整或合法（各单元格沿用现有兜底显示）。
344	  function isRoomRecord(value) {
345	    return value !== null && typeof value === 'object' && !Array.isArray(value);
346	  }
347	
348	  function appendSkipNotice(skipped, allSkipped) {
349	    var p = document.createElement('p');
350	    p.className = 'skip-notice';
351	    if (allSkipped) {
352	      p.textContent = '没有可展示的房间。本次返回的房间记录中有 ' + skipped +
353	        ' 条无法作为房间显示，已全部跳过；原始数据仍保留在服务端，未被删除或改写。';
354	    } else {
355	      p.textContent = '有 ' + skipped + ' 条房间记录无法作为房间显示，已跳过；' +
356	        '原始数据仍保留在服务端，未被删除或改写。';
357	    }
358	    listArea.appendChild(p);
359	  }
360	
361	  // 历史记录的某个展示字段若被存成 JSON 对象或数组，该单元格统一显示
362	  // “字段格式异常”，不展开其内部内容；异常只影响所在单元格，绝不能抛出
363	  // 异常拖垮整行乃至整份列表。null、字符串、数字、布尔值及缺失字段都不算
364	  // 异常，仍走各列原有的展示与兜底。
365	  var BAD_FIELD_TEXT = '字段格式异常';
366	  function isAbnormalField(value) {
367	    return value !== null && typeof value === 'object';
368	  }
369	  function markBadCell(td) {
370	    td.textContent = BAD_FIELD_TEXT;
371	  }
372	
373	  function appendBadge(td, text) {
374	    var badge = document.createElement('span');
